test('frame: double inversion at brick seam', () => {
  const state = createState(1);
  const brick0 = state.bricks[0];
  const brick1 = state.bricks[1]; // Next to brick0

  // Position ball so it overlaps both brick0 and brick1
  // Brick0: x=offsetX, w=72. Brick1: x=offsetX + 80.
  // Ball x = offsetX + 72 + 4 = offsetX + 76.
  // Ball r = 7. Left edge = 69, Right edge = 83.
  // Brick0 right edge = offsetX + 72. Brick1 left edge = offsetX + 80.
  // So it overlaps both.

  const offsetX = (WIDTH - (BRICK_COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;
  state.ball = {
    x: offsetX + BRICK_W + BRICK_GAP / 2,
    y: BRICK_TOP + BRICK_H / 2,
    r: 7,
    vx: 0,
    vy: 100,
  };

  const ctx = {
    fillRect: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {},
    beginPath: () => {},
    fillStyle: '',
    font: '',
  };

  frame(ctx, state);

  // If double inversion occurs, vy will be 100 (flipped twice).
  // It should be -100 (or at least have the sign of UP).
  assert.equal(Math.sign(state.ball.vy), UP, 'ball should still bounce up even when hitting two bricks');
});

